export const compileAllLibs = async (
		hOptions: hash = {}
		): AutoPromise<[TCounts, number, TExecResult[]]> => {

	type opt = {
		root: string
		}
	const {root} = getOptions<opt>(hOptions, {
		root: '.'
		})
	const pat = mkpath(root, '**/*.lib.civet')
	return await procFiles([doCompileCivet, [pat]], hOptions)
}

